"""Request and response shapes for deals: the deal page, edits, closing, next steps, Today."""

import uuid
from datetime import date, datetime
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field

from app.core.fields import Text500
from app.modules.leads.schemas import DealOut, LeadSource, PersonRef

Feedback = Literal["Accepted", "Changes requested", "Objections"]


class DealPatch(BaseModel):
    """Only these fields can be edited. Created date, created by and generated by are locked, so
    any other field is rejected (extra='forbid'). A field sent as null is emptied (refused for the
    ones that can never be empty)."""

    model_config = ConfigDict(extra="forbid")

    lead_source: LeadSource | None = None
    first_contact_date: date | None = None
    next_step_text: Text500 | None = None
    next_step_due_date: date | None = None
    expected_close_date: date | None = None
    expected_close_reason: str | None = None
    pricing_model: str | None = None
    plan: str | None = None
    expected_minutes_per_month: int | None = Field(default=None, ge=0)
    use_case: str | None = None
    pain_point: str | None = None
    budget_amount_paise: int | None = Field(default=None, ge=0)
    budget_source: str | None = None
    feedback: Feedback | None = None
    decision_date: date | None = None
    final_price_paise: int | None = Field(default=None, ge=0)
    scope: str | None = None
    agreed_by: str | None = None
    billing_contact: str | None = None
    subscription_start_date: date | None = None
    contract_term: str | None = None
    billing_frequency: str | None = None
    renewal_date: date | None = None
    go_live_date: date | None = None
    live_date: date | None = None
    live_note: str | None = None
    go_live_delayed: bool | None = None
    prereq_documents: str | None = None
    prereq_received_on: date | None = None
    technical_documents: str | None = None
    technical_received_on: date | None = None
    advance_amount_paise: int | None = Field(default=None, ge=0)
    advance_received_by: str | None = None
    advance_received_contact: str | None = None
    advance_received_on: date | None = None
    fit_checklist: dict[str, bool] | None = None
    custom_fields: dict[str, Any] | None = None
    expected_version: int | None = None
    reason: str | None = None


class UndoIn(BaseModel):
    audit_id: uuid.UUID


class LoseIn(BaseModel):
    model_config = ConfigDict(extra="forbid")

    lost_reason: str = Field(min_length=1)
    notes: str | None = None
    reason: str | None = None


class ReopenIn(BaseModel):
    reason: str | None = None


class DeleteIn(BaseModel):
    reason: str | None = None


class BulkLoseIn(BaseModel):
    deal_ids: list[uuid.UUID] = Field(min_length=1, max_length=500)
    lost_reason: str = Field(min_length=1)
    notes: str | None = None
    reason: str | None = None


class BulkSnoozeIn(BaseModel):
    deal_ids: list[uuid.UUID] = Field(min_length=1, max_length=500)
    reason: str | None = None


class BulkOwnerIn(BaseModel):
    deal_ids: list[uuid.UUID] = Field(min_length=1, max_length=500)
    user_id: uuid.UUID
    reason: str | None = None


class BulkOut(BaseModel):
    done: list[uuid.UUID]
    failed: list[dict[str, Any]]


class NextStepIn(BaseModel):
    model_config = ConfigDict(extra="forbid")

    text: str = Field(min_length=1, max_length=500)
    due_date: date
    responsible_id: uuid.UUID | None = None
    lane: Literal["your_move", "waiting_on_them"] = "your_move"
    reason: str | None = None


class StepDoneIn(BaseModel):
    """Done always comes with the next step: a deal is never left without one."""

    model_config = ConfigDict(extra="forbid")

    next: NextStepIn


class SnoozeIn(BaseModel):
    reason: str | None = None


class StageBar(BaseModel):
    key: str
    name: str
    group: str
    position: int
    probability_pct: int
    conditional: bool


class CriterionState(BaseModel):
    key: str
    label: str
    help_text: str | None
    proof_type: str
    ticked: bool
    status: str | None
    ticked_by: str | None
    ticked_at: datetime | None
    verified_by: str | None
    verify_reason: str | None
    proof_missing: bool
    ready: bool | None
    missing: list[str]


class Progress(BaseModel):
    stages: list[StageBar]
    current: str
    entry_id: uuid.UUID | None
    criteria: list[CriterionState]


class ContactRow(BaseModel):
    id: uuid.UUID
    name: str
    role: str | None
    phone: str | None
    email: str | None
    is_decision_maker: bool


class FitRow(BaseModel):
    id: uuid.UUID
    label: str
    ticked: bool


class CustomRow(BaseModel):
    key: str
    label: str
    type: str
    options: list[Any]
    value: Any


class StageVisit(BaseModel):
    stage_key: str
    stage_name: str
    entered_at: datetime
    exited_at: datetime | None
    exit_kind: str | None
    reason: str | None
    revision_round: int


class DealDetail(DealOut):
    stage_name: str
    probability_pct: int | None
    pricing_model: str | None
    plan: str | None
    expected_minutes_per_month: int | None
    use_case: str | None
    pain_point: str | None
    expected_close_reason: str | None
    lost_reason: str | None
    lost_notes: str | None
    lost_from_stage: str | None
    data: dict[str, Any]
    fit: list[FitRow]
    custom: list[CustomRow]
    contacts: list[ContactRow]
    progress: Progress
    visits: list[StageVisit]
    deleted: bool = False
    deleted_reason: str | None = None
    owner_hidden: bool = False


class StepRow(BaseModel):
    id: uuid.UUID
    deal_id: uuid.UUID
    company: str
    text: str
    due_date: date
    lane: str
    lane_since: datetime
    snooze_count: int
    overdue: bool
    nudge_due: bool
    health: str
    stage_key: str
    stage_name: str
    value_paise: int
    flags: dict[str, Any]
    owner: PersonRef | None
    assigned_by: str | None


class TodayOut(BaseModel):
    user: PersonRef
    your_move: list[StepRow]
    waiting_on_them: list[StepRow]
    stale: list[StepRow]
    new_leads: list[StepRow]
    counts: dict[str, int]
